import{_ as a,H as n,f as e,i}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"第3章远程登录Linux系统","description":"","frontmatter":{},"headers":[{"level":2,"title":"3.1 安装 PuTTY","slug":"_3-1-安装-putty","link":"#_3-1-安装-putty","children":[{"level":3,"title":"3.1.1 下载 PuTTY","slug":"_3-1-1-下载-putty","link":"#_3-1-1-下载-putty","children":[]},{"level":3,"title":"3.1.2 安装","slug":"_3-1-2-安装","link":"#_3-1-2-安装","children":[]}]},{"level":2,"title":"3.2 远程登录","slug":"_3-2-远程登录","link":"#_3-2-远程登录","children":[{"level":3,"title":"3.2.1 使用密码直接登录","slug":"_3-2-1-使用密码直接登录","link":"#_3-2-1-使用密码直接登录","children":[]},{"level":3,"title":"3.2.2 使用密钥认证","slug":"_3-2-2-使用密钥认证","link":"#_3-2-2-使用密钥认证","children":[]}]},{"level":2,"title":"3.3 两台 Linux 相互登录","slug":"_3-3-两台-linux-相互登录","link":"#_3-3-两台-linux-相互登录","children":[{"level":3,"title":"3.3.1 克隆 CentOS","slug":"_3-3-1-克隆-centos","link":"#_3-3-1-克隆-centos","children":[]},{"level":3,"title":"3.3.2 使用密码登录","slug":"_3-3-2-使用密码登录","link":"#_3-3-2-使用密码登录","children":[]},{"level":3,"title":"3.3.3 使用密钥登录","slug":"_3-3-3-使用密钥登录","link":"#_3-3-3-使用密钥登录","children":[]}]},{"level":2,"title":"3.4 课后习题","slug":"_3-4-课后习题","link":"#_3-4-课后习题","children":[]}],"relativePath":"跟阿铭学Linux/第3章远程登录Linux系统.md","filePath":"跟阿铭学Linux/第3章远程登录Linux系统.md","lastUpdated":1795561067000}'),p={name:"跟阿铭学Linux/第3章远程登录Linux系统.md"};function l(t,s,o,c,u,h){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="第3章远程登录linux系统" tabindex="-1">第3章远程登录Linux系统 <a class="header-anchor" href="#第3章远程登录linux系统" aria-label="Permalink to &quot;第3章远程登录Linux系统&quot;">​</a></h1><p>Linux 主要应用于服务器领域，而服务器不可能像 PC 机那样放在办公室，它们是放在 IDC 机房的，所以阿铭平时登录 Linux 系统都是通过网络远程登录的。</p><p>Linux 系统通过 sshd 服务实现远程登录功能。sshd 服务默认开启了 22 端口，当我们安装完系统时，这个服务已经安装，并且是开机启动的。所以，我们不需要额外配置什么就能直接远程登录 Linux 系统。sshd 服务的配置文件为 /etc/ssh/sshd_config，你可以根据需求修改这个配置文件，比如可以更改启动端口为 11587，注意这个数字不能超过 65535。</p><p>如果你安装的是 Windows 操作系统，则需要额外安装一个 Linux 远程登录的终端软件。目前比较常见的终端登录软件有 Xshell、SecureCRT、PuTTY、SSH Secure Shell 等。很多朋友喜欢用 SecureCRT，因为它的功能非常强大，但阿铭喜欢用 PuTTY，因为它小巧且显示的颜色漂亮。最近阿铭也在使用 Xshell，这个软件也非常不错，值得大家研究一下。但不管你使用哪一个客户端软件，最终的目的只有一个——远程登录到 Linux 服务器上。</p><h2 id="_3-1-安装-putty" tabindex="-1">3.1 安装 PuTTY <a class="header-anchor" href="#_3-1-安装-putty" aria-label="Permalink to &quot;3.1 安装 PuTTY&quot;">​</a></h2><p>PuTTY 是一个免费的、开源的 SSH 客户端软件，它不仅有 Windows 版本，还有 Unix/Linux版本。PuTTY 的操作和配置都非常简单、易用。</p><h3 id="_3-1-1-下载-putty" tabindex="-1">3.1.1 下载 PuTTY <a class="header-anchor" href="#_3-1-1-下载-putty" aria-label="Permalink to &quot;3.1.1 下载 PuTTY&quot;">​</a></h3><p>网上曾经报道过，某个中文版的 PuTTY 被别有用心的黑客动了手脚，给植了后门。所以阿铭提醒各位，以后不管下载什么软件，尽量去官方站点下载。当然，你也可以通过阿铭在前言的反馈及服务中提供的途径去下载。打开下载页面后，我们可以看到有很多软件可供下载，如下所示：</p><ul><li><p>PuTTY（SSH 和 telnet 客户端软件）；</p></li><li><p>PSCP（SCP 客户端，用来远程复制文件）；</p></li><li><p>PSFTP（SFTP 客户端软件，使用 SSH 协议传输文件）；</p></li><li><p>PuTTYtel（一个只有 telnet 功能的客户端软件）；</p></li><li><p>Plink（Windows 下的命令行接口，使用它可以在 cmd 下使用 PuTTY）；</p></li><li><p>Pageant（SSH 的密钥守护进程，开启该进程后，密钥保存到内存中，连接时不再输入密钥的密码，PuTTY、PSCP、PSFTP 和 Plink 都可以使用它）；</p></li><li><p>PuTTYgen（生成密钥对的工具，3.2.2 节会用到它）。</p></li></ul><p>如果你只想用 PuTTY，那只需下载 putty.exe 即可，不过后面我们还会用到 PuTTYgen 和PSFTP，所以阿铭建议你干脆下载安装包 putty-0.73-installer.msi（版本可能已经更新，下载最新版本即可），然后安装一下，这样所有的软件都全了。</p><h3 id="_3-1-2-安装" tabindex="-1">3.1.2 安装 <a class="header-anchor" href="#_3-1-2-安装" aria-label="Permalink to &quot;3.1.2 安装&quot;">​</a></h3><p>下载安装包后，双击 putty-0.73-installer.msi 进入安装界面，所有配置都保持默认设置，直接单击 Next 按钮，直至安装结束。安装完成后，在“开始”菜单中找到 PuTTY，单击即可打开这个软件。</p><h2 id="_3-2-远程登录" tabindex="-1">3.2 远程登录 <a class="header-anchor" href="#_3-2-远程登录" aria-label="Permalink to &quot;3.2 远程登录&quot;">​</a></h2><p>在第 2 章中，我们已经给 CentOS 设置了 IP 地址（192.168.72.128），并且这个 IP 地址是静态的，即使你的 VMware 重启过，它也不会变。设置 IP 地址的目的除了要使用 yum 工具外，另一个就是远程连接 Linux 操作系统了。</p><h3 id="_3-2-1-使用密码直接登录" tabindex="-1">3.2.1 使用密码直接登录 <a class="header-anchor" href="#_3-2-1-使用密码直接登录" aria-label="Permalink to &quot;3.2.1 使用密码直接登录&quot;">​</a></h3><p>打开 PuTTY 后，请按照如下步骤连接远程 Linux 服务器。</p><ol><li>填写远程 Linux 的基本信息填写 Linux 基本信息的对话框如图 3-1 所示，其中 Host Name(or IP address) 这一栏填写服务器 IP，即 192.168.72.128，Port 和 Connection type 这两栏采用默认设置即可。</li></ol><ul><li>Saved Sessions 这一栏自定义一个名字，主要用来区分主机，因为将来你的主机会很多，写个简单的名字既方便记忆又能快速查找。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/1.png" alt=""></a></p><ul><li>图 3-1 填写基本信息</li></ul><ol start="2"><li>定义字符集计算机的字符集是最麻烦的，尤其是 Linux，搞不好就会乱码。阿铭在第 2 章中教你安装CentOS 时已经安装了中文语言，所以安装好的系统支持中文。在 PuTTY 这里也要设置支持中文，单击左侧的 Window→Translation，查看右侧的 Character set translation，选择UTF-8，如图 3-2 所示。再单击左侧的 Session，然后单击右侧的 Save 按钮。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/2.png" alt=""></a></p><ul><li>图 3-2 定义字符集</li></ul><ol start="3"><li>远程连接你的 Linux保存 Session 后，单击最下方的 Open 按钮。初次登录时，都会弹出一个友情提示，它的意思是要打开的 Linux 还未在本机登记，问我们是否要信任这个 Linux。如果是可信任的，则单击“是”按钮在该主机登记；否则单击“否”按钮或者“取消”按钮。这里我们单击“是”按钮，弹出如下登录提示：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>login as: root</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>root@192.168.72.128&#39;s password:</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>Last login: Thu Dec 26 08:13:39 2019</span></span>
<span class="line"><span>3</span></span></code></pre></div><ul><li>输入用户名和密码后，就可以登录 Linux 系统。登录后，会提示至目前最后一次登录系统的时间和地点。然后，我们就可以在 PuTTY 里面进行操作了，这和在 VMware 终端上操作没有区别。而且它还有一个好处，就是可以随意复制、粘贴。之前在终端的窗口里，我们没有办法复制内容，更不能粘贴文本信息。使用 PuTTY，我们还可以通过鼠标滚轮翻查之前显示的历史信息。</li></ul><h3 id="_3-2-2-使用密钥认证" tabindex="-1">3.2.2 使用密钥认证 <a class="header-anchor" href="#_3-2-2-使用密钥认证" aria-label="Permalink to &quot;3.2.2 使用密钥认证&quot;">​</a></h3><p>SSH 服务支持一种安全认证机制，即密钥认证。所谓密钥认证，实际上是使用一对加密的字符串：其中一个称为公钥（public key），用于加密，任何人都可以看到其内容；另一个称为私钥（private key），用于解密，只有拥有者才能看到其内容。通过公钥加密过的密文，使用私钥可以轻松解密，但根据公钥来猜测私钥却十分困难。SSH 的密钥认证就是使用了这一特性。</p><p>服务器和客户端都各自拥有自己的公钥和私钥，PuTTY 可以使用密钥认证登录 Linux，具体的操作步骤如下。</p><ol><li>生成密钥对关于密钥对的工作原理，如果感兴趣，可以到网上查一查，阿铭在此不过多介绍。在“开始”菜单中找到 PuTTYgen，单击打开它，如图 3-3 所示。然后单击 Generate 按钮，这样就开始生成密钥了，请来回拨动鼠标，这样有助于快速生成密钥对，大约几秒钟就完成了。图3-3 中的 Key comment 可以保持不变，也可以自定义，它是对该密钥的简单介绍。Keypassphrase 用于给你的密钥设置密码，此项可以留空，但阿铭建议你设置一个，这样安全一些。Confirm passphrase 需要再输入一遍刚刚设置的密码。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/3.png" alt=""></a></p><ul><li>图 3-3 生成密钥对</li></ul><ol start="2"><li><p>保存私钥单击 Save private key 按钮，选择一个存放路径并定义名称，单击“保存”按钮。这个就是私钥，请把它保存到一个比较安全的地方，谨防丢失或被其他人看到。</p></li><li><p>复制公钥到 Linux返回刚才生成密钥对的窗口，在 Key 的下方有一个长字符串，这个字符串就是公钥的内容。把整个公钥字符串复制下来，粘贴到 Linux 的文件中。下面请跟着阿铭一起来操作，运行如下命令：</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># mkdir /root/.ssh</span><span> // 创建/root/.ssh目录，因为这个目录默认是不存在的</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span># chmod 700 /root/.ssh</span><span> // 更改这个目录的权限</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span># vi /root/.ssh/authorized_keys</span><span> // 把公钥内容粘贴到文件/root/.ssh/authorized_keys里</span></span>
<span class="line"><span>关于mkdir和chmod这两个命令，阿铭会分别在 4.1.2 节和 4.6.3 节中详细介绍。在vi命</span></span>
<span class="line"><span>令之后直接回车，输入i进入编辑模式，然后单击鼠标右键就可以粘贴了，这是 PuTTY 工</span></span></code></pre></div><ul><li>具非常方便的一个功能。粘贴后，按 Esc 键，然后输入:wq 并回车，保存并退出该文件。</li></ul><ol start="4"><li>关闭 SELinux关于 SELinux，在第 2 章中我们也提到过，它是 CentOS 的一种安全机制，它的存在虽然让 Linux 系统安全了很多，但也产生了不少麻烦。这里如果不关闭 SELinux，使用密钥登录</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时会提示Server refused our key，从而导致不能成功。需要运行如下命令来关闭</span></span></code></pre></div><ul><li>SELinux：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># setenforce 0</span></span>
<span class="line"><span>1</span></span></code></pre></div><ul><li>这只是暂时关闭，下次重启 Linux 后，SELinux 还会开启。若要永久关闭，必须运行如下命令：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vi /etc/selinux/config</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>按回车后，把光标移动到SELINUX=enforcing这一行，输入i进入编辑模式，修改为</span></span>
<span class="line"><span>SELINUX= disabled。按 Esc 键，然后输入:wq 并回车，最后重启系统。</span></span></code></pre></div><ol start="5"><li>设置 PuTTY 通过密钥登录当系统重新启动后，打开 PuTTY 软件，在右侧 Saved Sessions 下面找到刚刚保存的session，单击选中它，然后再单击右侧的 Load 按钮。在左下方单击 SSH 前面的 +，然后选择 Auth，查看右侧 Private key file for authentication 下面的长条框，目前为空。单击Browse 按钮，找到我们刚刚保存好的私钥，单击“打开”按钮。此时这个长条框里就有了私钥的地址（当然，你也可以自行编辑这个路径），如图 3-4 所示。最后，再回到左侧，单击最上面的 Session，再单击右侧的 Save 按钮。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/4.png" alt=""></a></p><ul><li>图 3-4 设置密钥</li></ul><ol start="6"><li>使用密钥验证登录 Linux保存好 Session 后，单击右下方的 Open 按钮，会出现登录界面，此时你会发现，登录提示内容和原来的有所不同，如下所示：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>login as: root</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>Authenticating with public key &quot;rsa-key-20191227&quot;</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>Passphrase for key &quot;rsa-key-20191227&quot;:</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>Last login: Fri Dec 27 06:42:50 2019 from 192.168.72.1</span></span></code></pre></div><ul><li><p>这里不再是输入 root 密码，而是需要输入密钥的密码。如果先前生成密钥对时你没有设置密码，输入 root 后会直接登录系统。有很多朋友在做密钥认证的时候会失败，但只要注意这几点就一定可以成功：</p></li><li><p>/root/.ssh 目录权限为 700；</p></li><li><p>SELinux 要关闭；</p></li><li><p>/root/.ssh/authorized_keys 文件名要写对；</p></li><li><p>文件内容要粘贴对。</p></li><li><p>假如你还有一台机器需要使用密钥验证登录 Linux，你学会如何设置了吗？PuTTY 的设置方法是一样的，使用同样的私钥，不需要你再次生成密钥对了。另外，把 192.168.72.128上的文件 /root/.ssh/authorized_keys 复制一份到另一台机器就可以了。请注意，这个文件的名字是固定的。</p></li><li><p>在本例中，阿铭教大家的是直接使用密钥登录 root 用户，但在工作中很多朋友登录的是普通用户，而不是 root。那普通用户的密钥认证如何设置呢？原理肯定是一样的，同样要先有密钥对，然后把公钥放到服务器上，不过不是在 /root/.ssh 目录下面了，而是普通用户家目录下面的.ssh 目录下。那普通用户家目录在哪里？第 5 章讲到用户管理时，阿铭会详细介绍，在这阿铭举一个例子，比如你登录的普通用户为 aming，那么 aming 用户的家目录为/home/aming。还有一点大家要注意，在 Linux 机器上所做的操作（如创建.ssh 目录）也必须以 aming 用户身份操作才可以。</p></li></ul><h2 id="_3-3-两台-linux-相互登录" tabindex="-1">3.3 两台 Linux 相互登录 <a class="header-anchor" href="#_3-3-两台-linux-相互登录" aria-label="Permalink to &quot;3.3 两台 Linux 相互登录&quot;">​</a></h2><p>既然可以在 Windows 上安装一个客户端软件（比如 PuTTY）去登录远程的 Linux，那么在Linux 上是否也可以登录另一台 Linux 呢？当然可以，只是在 Linux 上也需要安装一个客户端软件。CentOS 自带的客户端软件叫作 openssh-clients。</p><p>要想检测 Linux 上是否已安装客户端软件，需要运行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ssh -V</span></span>
<span class="line"><span>OpenSSH_7.8p1, OpenSSL 1.1.1 FIPS 11 Sep 2018</span></span></code></pre></div><p>如果已安装，则会显示 OpenSSH 的版本信息。如果没有显示类似的信息，请运行如下命令安装：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># yum install -y openssh-clients</span></span></code></pre></div><h3 id="_3-3-1-克隆-centos" tabindex="-1">3.3.1 克隆 CentOS <a class="header-anchor" href="#_3-3-1-克隆-centos" aria-label="Permalink to &quot;3.3.1 克隆 CentOS&quot;">​</a></h3><p>要完成本实验，还需要有一台 Linux 机器，你可以按照 2.2 节再安装一台 CentOS。但阿铭觉得那样做太浪费时间，其实还有一个更好的方法——克隆虚拟机。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首先，关闭正在运行的 CentOS，正确的关机命令是shutdown -h now或者init 0。然后</span></span></code></pre></div><p>在左侧对应的虚拟机名字上单击鼠标右键，选择“管理”，再选择“克隆”，如图 3-5 所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B7%9F%E9%98%BF%E9%93%AD%E5%AD%A6Linux/images/%25E7%25AC%25AC3%25E7%25AB%25A0%25E8%25BF%259C%25E7%25A8%258B%25E7%2599%25BB%25E5%25BD%2595Linux%25E7%25B3%25BB%25E7%25BB%259F/5.png" alt=""></a></p><p>图 3-5 克隆</p><p>此时会出现“克隆向导”界面。直接单击“下一步”按钮，再单击“下一步”按钮，会出现“克隆类型”对话框，这里采用默认值即可，即选择“创建链接克隆”，这种类型会节省空间，比较方便。继续单击“下一步”按钮，你可以设定克隆虚拟机的名称和保存的路径。接着单击“完成”和“关闭”按钮，最终完成 CenOS 8 的克隆。此时，不管是在左侧“我的电脑”下面还是在右侧“选项卡”，都多出来一个克隆后的 CentOS 8 虚拟机。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把两台 CentOS 7 全部启动。先登录克隆的虚拟机，输入命令dhclient，让这台新克隆的</span></span>
<span class="line"><span>CentOS 8 也自动获取一个 IP 地址。再运行ip addr命令，可以看到获取到的 IP 地址为</span></span></code></pre></div><p>192.168.72.129，使用 2.3.2 节的方法给这台 CentOS 8 也配置一个静态 IP 地址。</p><p>为了便于区分两台 CentOS 8，下面阿铭教你如何设置主机名。我们不妨给第一台起个主机名为 aminglinux-128，第二台为 aminglinux-129。请在第一台 CentOS 8 上运行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># hostnamectl set-hostname aminglinux-128</span></span></code></pre></div><p>可以使用快捷键 Ctrl+D 退出当前终端，然后再登录一次，就会发现命令行左边的前缀有所变化了。使用同样的方法，将第二台 CentOS 8 的主机名设置为 aminglinux-129。</p><h3 id="_3-3-2-使用密码登录" tabindex="-1">3.3.2 使用密码登录 <a class="header-anchor" href="#_3-3-2-使用密码登录" aria-label="Permalink to &quot;3.3.2 使用密码登录&quot;">​</a></h3><p>使用前面的方法，通过 PuTTY 远程登录 aminglinux-128，然后在这台机器上执行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ssh root@192.168.72.129</span><span> // 第一次登录对方机器，有一个提示</span></span>
<span class="line"><span>The authenticity of host &#39;192.168.188.129 (192.168.72.129)&#39; can&#39;t be established.</span></span>
<span class="line"><span>ECDSA key fingerprint is 26:e3:97:e7:bb:ae:17:33:ea:aa:0c:5f:37:0e:9e:fa.</span></span>
<span class="line"><span>Are you sure you want to continue connecting (yes/no)</span></span></code></pre></div><p>这里我们输入 yes，然后回车，又出现一个如下的警告，它的意思是保存了 192.168.72.129这台机器的信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Warning: Permanently added &#39;192.168.72.129&#39; (ECDSA) to the list of known hosts.</span></span>
<span class="line"><span>root@192.168.72.129&#39;s password:</span></span></code></pre></div><p>然后输入 192.168.72.129 的 root 密码后，成功登录 aminglinux-129。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令中符号@前面的root表示要以远程机器哪个用户的身份登录。我们可以省略root@，即</span></span>
<span class="line"><span>写成ssh 192.168.72.129，它也表示以 root 用户的身份登录。这个并不是固定的，取决</span></span></code></pre></div><p>于当前系统的当前用户是谁。我们可以使用如下命令查看当前用户：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># whoami</span></span>
<span class="line"><span>root</span></span></code></pre></div><p>也可以写成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># who am i</span></span>
<span class="line"><span>root pts/1 2019-12-27 07:06 (192.168.72.128)</span></span></code></pre></div><p>从这两个命令的显示结果可以看出它们的区别：一个是简单显示，一个是复杂显示。后者不仅可以显示当前用户名，还可以显示登录的终端、登录时间以及从哪里登录。</p><h3 id="_3-3-3-使用密钥登录" tabindex="-1">3.3.3 使用密钥登录 <a class="header-anchor" href="#_3-3-3-使用密钥登录" aria-label="Permalink to &quot;3.3.3 使用密钥登录&quot;">​</a></h3><p>既然 PuTTY 支持使用密钥验证的方式登录 Linux 机器，那么 Linux 下的客户端软件也是支持的。下面请跟着阿铭一步一步来操作。</p><ol><li>客户端生成密钥对假如 aminglinux-128 为客户端（以下简称 128），aminglinux-129 为要登录的机器（以下简称 129）。首先，把刚刚登录的 129 退出来，直接使用 Ctrl+D 快捷键即可。然后在 128 上执行如下命令：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ssh-keygen</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>Generating public/private rsa key pair.</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>Enter file in which to save the key (/root/.ssh/id_rsa):</span></span>
<span class="line"><span>3</span></span></code></pre></div><ul><li>这个命令用来生成密钥对。首先，它让我们定义私钥的存放路径，默认路径为 /root/.ssh/id_rsa。这里采用默认值即可，直接回车，此时会显示如下信息：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enter passphrase (empty for no passphrase):</span></span>
<span class="line"><span>1</span></span></code></pre></div><ul><li>然后它让我们定义私钥的密码，可以留空，直接回车即可，此时会显示如下信息：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enter same passphrase again:</span></span>
<span class="line"><span>1</span></span></code></pre></div><ul><li>此时它让我们再一次输入密码，输入然后回车，此时会显示如下信息：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your identification has been saved in /root/.ssh/id_rsa.</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>Your public key has been saved in /root/.ssh/id_rsa.pub.</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>The key fingerprint is:</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>57:15:10:d6:8a:ed:79:83:0b:fc:d7:21:52:5b:ba:83 root@aminglinux-128</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>The key&#39;s randomart image is:</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span>+--[ RSA 2048]----+</span></span>
<span class="line"><span>6</span></span>
<span class="line"><span>| ++o. |</span></span>
<span class="line"><span>7</span></span>
<span class="line"><span>| . .. |</span></span>
<span class="line"><span>8</span></span>
<span class="line"><span>| o.. |</span></span>
<span class="line"><span>9</span></span>
<span class="line"><span>| ..o. . |</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>| S....o+ |</span></span>
<span class="line"><span>11</span></span>
<span class="line"><span>| .o.++o. |</span></span>
<span class="line"><span>12</span></span>
<span class="line"><span>| ooooo.|</span></span>
<span class="line"><span>13</span></span>
<span class="line"><span>| Eoo. .|</span></span>
<span class="line"><span>14</span></span>
<span class="line"><span>| .. |</span></span>
<span class="line"><span>15</span></span>
<span class="line"><span>+-----------------+</span></span>
<span class="line"><span>16</span></span></code></pre></div><ul><li>最终生成了密钥对，你可以在 /root/.ssh/ 目录下找到公钥（id_rsa.pub）和私钥（id_rsa）。</li></ul><ol start="2"><li>把公钥复制到要登录的机器上首先，我们查看 128 上公钥的内容，此时运行如下命令：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cat /root/.ssh/id_rsa.pub</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQDiAUXQihX9pa1oxml6xRjZhjTRCU+QMHUGXU34Q6g</span></span>
<span class="line"><span>2</span></span></code></pre></div><ul><li>将这些字符串全部复制，然后粘贴到 129 上的文件 /root/.ssh/authorized_keys 里。若之前已经创建过这个文件，并且已经粘贴过 PuTTY 的公钥，则需要另起一行粘贴 128 的公钥。在 129 上执行如下命令：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vi /root/.ssh/authorized_keys</span></span>
<span class="line"><span>1</span></span></code></pre></div><ul><li>如果有内容，可以按字母键 G 把光标定位到文件末尾，然后输入 o 进入编辑模式（这里使用的命令和之前有所不同，请先跟着阿铭操作）。单击鼠标右键即可粘贴 128 的公钥。然后按 Esc 键，输入:wq，再回车。如果你之前并没有设置 PuTTY 的公钥，请继续执行以下命令：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># chmod 600 /root/.ssh/authorized_keys</span></span>
<span class="line"><span>1</span></span></code></pre></div><ol start="3"><li>登录 Linux在 128 上执行如下命令：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ssh 192.168.72.129</span></span>
<span class="line"><span>1</span></span></code></pre></div><ul><li>此时不再提示我们输入密码，就可以直接登录到 129 了。这样就可以实现 Linux 通过密钥验证的方式登录 Linux。如果你在生成密钥对时设置了密码，那么这里也会提示你输入密钥密码。为了方便跨机器执行命令，这里我们特意不设置密钥的密码（后面会用到）。</li></ul><ol start="4"><li>使用 ssh-copy-idLinux 系统里还有一种更方便实现密钥认证的方法。这次阿铭要让 129 通过密钥认证登录128。在 129 上执行如下命令：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ssh-keygen</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span># ssh-copy-id root@192.168.72.128</span></span>
<span class="line"><span>2</span></span></code></pre></div><ul><li>它会提示让我们输入 128 的 root 密码，只要输入对了对方服务器的密码就完成了密钥认证。再次尝试 ssh 登录 128，此时就不再提示我们输入密码，可以直接登录到 129 了。</li></ul><h2 id="_3-4-课后习题" tabindex="-1">3.4 课后习题 <a class="header-anchor" href="#_3-4-课后习题" aria-label="Permalink to &quot;3.4 课后习题&quot;">​</a></h2><p>(1) 远程连接 Linux 服务器，需要 Linux 服务器开启 sshd 服务，那么 sshd 服务默认监听哪个端口？这个端口是否可以自定义呢？如果可以，如何自定义呢？</p><p>(2) 常用的远程连接 Linux 的终端工具有哪些？</p><p>(3) 手动配置 IP 需要修改哪个配置文件？更改默认的配置文件需要修改哪些地方？</p><p>(4) 重启网络服务的命令是什么？</p><p>(5) 如何临时关闭 SELinux？如何永久关闭 SELinux？</p><p>(6) 查看 Linux 有几块网卡用什么命令？查看网卡 IP 用什么命令？</p><p>(7) 我们为什么要使用密钥登录 Linux 呢？</p>`,108)])])}const g=a(p,[["render",l]]);export{r as __pageData,g as default};
